Check the sandbox environment (Python/numpy versions, numba availability, C compiler, CPU) to choose an efficient cluster-update implementation.</purpose>
<parameter name="code">import sys, subprocess, shutil, os, platform
print("python", sys.version)
try:
    import numpy as np
    print("numpy", np.__version__)
except Exception as e:
    print("numpy err", e)
try:
    import scipy
    print("scipy", scipy.__version__)
except Exception as e:
    print("scipy err", e)
try:
    import numba
    print("numba", numba.__version__)
except Exception as e:
    print("numba not available:", e)
for c in ["gcc", "cc", "clang", "tcc"]:
    print(c, shutil.which(c))
print("platform", platform.platform())
print("cpu count", os.cpu_count())
try:
    print(subprocess.run(["bash","-lc","cat /proc/cpuinfo | grep 'model name' | head -2; free -m; ls -la /work 2>/dev/null; echo $PWD"],capture_output=True,text=True).stdout)
except Exception as e:
    print(e)

